//! 📥️ Actual Source return claims deliver the same fault capsule into its rooted recipient.
use super::{ActorFailureCapsule,ActorFailurePermit,pay_many,refused};
use semio_framework_actor::{ActorFailureCallReference,retained_context::OriginalActorReturnSlot};
use semio_framework_job::{OriginalNativeBorrowed,OriginalNativeRecipientIdentity,OriginalNativeRetirement,OriginalSourceBinding,OriginalTurnFailure,StepContext};
use semio_framework_value::ValueError;
use std::mem::size_of;
/// 🏠️ The recipient owns the actual fault lease until its own funded retirement.
pub struct ActorFailureRecipientHome{capsule:Option<ActorFailureCapsule>}
impl ActorFailureRecipientHome{pub const fn empty()->Self{Self{capsule:None}}pub fn receive_step(&mut self,capsule:&mut Option<ActorFailureCapsule>,permit:&ActorFailurePermit,cx:&mut StepContext<'_>)->Result<bool,OriginalTurnFailure>{if self.capsule.is_some()||capsule.as_ref().is_none_or(|capsule|!capsule.qualifies(permit,cx)){return Err(refused().into())}if !pay_many(cx,2,2*size_of::<Option<ActorFailureCapsule>>(),0)?{return Ok(false)}self.capsule=capsule.take();Ok(true)}pub fn with_bytes_step(&mut self,cx:&mut StepContext<'_>,receive:impl FnOnce(&[u8],&mut StepContext<'_>)->Result<(),OriginalTurnFailure>)->Result<bool,OriginalTurnFailure>{self.capsule.as_mut().ok_or_else(refused)?.with_bytes(cx,receive)}}
impl OriginalNativeRetirement for ActorFailureRecipientHome{fn close_on_source(&mut self,cx:&mut StepContext<'_>)->Result<bool,OriginalTurnFailure>{if let Some(capsule)=self.capsule.as_mut(){if !capsule.return_step(cx)?{return Ok(false)}if !pay_many(cx,1,size_of::<Option<ActorFailureCapsule>>(),0)?{return Ok(false)}self.capsule.take();return Ok(false)}Ok(true)}fn terminal_is_empty(&self)->bool{self.capsule.is_none()}}
/// 🪪️ Only an actual rooted, written and settled recipient can mint this acceptance.
pub struct ActorFailureRecipientAccepted{producer:OriginalNativeRecipientIdentity,recipient:OriginalNativeRecipientIdentity,reference:ActorFailureCallReference,binding:OriginalSourceBinding,home:usize}
impl ActorFailureRecipientAccepted{pub fn proves(&self,permit:&ActorFailurePermit,cx:&StepContext<'_>)->bool{self.producer==permit.producer()&&self.reference==permit.reference()&&self.binding.matches(cx)&&permit.proves(self.recipient,cx)&&self.home!=0}pub fn reference(&self)->ActorFailureCallReference{self.reference}}
/// 📮️ Both the receiver target and its temporary donor stay in their admitted native home.
pub struct ActorFailureRecipient{slot:OriginalActorReturnSlot<ActorFailureRecipientHome>,seed:Option<ActorFailureRecipientHome>,acquired:bool,returned:bool,ready:bool,closing:bool,binding:Option<OriginalSourceBinding>,home:usize}
impl ActorFailureRecipient{pub const fn empty()->Self{Self{slot:OriginalActorReturnSlot::empty(),seed:None,acquired:false,returned:false,ready:false,closing:false,binding:None,home:0}}
 fn validate(&self,cx:&StepContext<'_>)->Result<(),OriginalTurnFailure>{cx.original_source_parent()?.validate_borrowed_context(cx)?;if self.home!=0&&self.home!=self as*const Self as usize||self.binding.is_some_and(|binding|!binding.matches(cx)){return Err(refused().into())}Ok(())}
 pub fn prepare_step(&mut self,cx:&mut StepContext<'_>)->Result<bool,OriginalTurnFailure>{self.validate(cx)?;if self.binding.is_none(){if !pay_many(cx,2,size_of::<Option<OriginalSourceBinding>>()+size_of::<usize>(),0)?{return Ok(false)}self.binding=Some(OriginalSourceBinding::borrow(cx));self.home=self as*const Self as usize;return Ok(false)}if self.closing{return Err(refused().into())}if self.ready{return Ok(true)}if self.returned{if !self.slot.settle_step(cx)?{return Ok(false)}if !pay_many(cx,3,3*size_of::<bool>(),0)?{return Ok(false)}self.acquired=false;self.returned=false;self.ready=true;return Ok(true)}if !self.acquired&&!self.slot.lend_step(&mut self.seed,&mut self.acquired,cx)?{return Ok(false)}if self.seed.is_none(){if !pay_many(cx,1,size_of::<Option<ActorFailureRecipientHome>>(),0)?{return Ok(false)}self.seed=Some(ActorFailureRecipientHome::empty());return Ok(false)}self.slot.return_owner_step(&mut self.seed,&mut self.returned,cx)?;Ok(false)}
 pub fn lend_step(&mut self,donor:&mut Option<ActorFailureRecipientHome>,acquired:&mut bool,cx:&mut StepContext<'_>)->Result<bool,OriginalTurnFailure>{self.validate(cx)?;if !self.ready||self.closing||self.slot.peek().is_some_and(|home|home.capsule.is_some()){return Err(refused().into())}self.slot.lend_step(donor,acquired,cx)}
 pub fn return_home_step(&mut self,donor:&mut Option<ActorFailureRecipientHome>,written:&mut bool,cx:&mut StepContext<'_>)->Result<bool,OriginalTurnFailure>{self.validate(cx)?;if !self.ready||self.closing{return Err(refused().into())}self.slot.return_owner_step(donor,written,cx)}
 pub fn return_home(&mut self,donor:&mut Option<ActorFailureRecipientHome>)->Result<(),ValueError>{if !self.ready||self.closing{return Err(refused())}self.slot.return_owner(donor)}
 pub fn accept_into_step<T:OriginalNativeRetirement>(mut producer:OriginalNativeBorrowed<'_,T>,project:impl for<'a>FnOnce(&'a mut T)->Result<(&'a mut Self,&'a ActorFailurePermit,&'a mut Option<ActorFailureRecipientAccepted>),OriginalTurnFailure>,cx:&mut StepContext<'_>)->Result<bool,OriginalTurnFailure>{producer.validate_context(cx)?;let identity=producer.recipient_identity();let(recipient,permit,out)=project(producer.value_mut())?;if out.is_some(){return Err(refused().into())}if identity!=permit.producer(){return Err(refused().into())}recipient.validate(cx)?;if !recipient.ready||recipient.closing||!recipient.slot.settle_step(cx)?{return Ok(false)}let home=recipient.slot.peek().ok_or_else(refused)?;let capsule=home.capsule.as_ref().filter(|capsule|capsule.qualifies(permit,cx)).ok_or_else(refused)?;let native=capsule.native.as_ref().ok_or_else(refused)?.recipient_identity();if !pay_many(cx,1,size_of::<Option<ActorFailureRecipientAccepted>>(),0)?{return Ok(false)}*out=Some(ActorFailureRecipientAccepted{producer:permit.producer(),recipient:native,reference:permit.reference(),binding:OriginalSourceBinding::borrow(cx),home:home as*const ActorFailureRecipientHome as usize});Ok(true)}
}
impl OriginalNativeRetirement for ActorFailureRecipient{fn close_on_source(&mut self,cx:&mut StepContext<'_>)->Result<bool,OriginalTurnFailure>{if self.terminal_is_empty(){return Ok(true)}self.validate(cx)?;if self.slot.terminal_is_empty()&&self.seed.is_none()&&!self.acquired&&!self.returned&&!self.ready{if !pay_many(cx,2,size_of::<Option<OriginalSourceBinding>>()+size_of::<usize>(),0)?{return Ok(false)}self.binding=None;self.home=0;return Ok(true)}if !self.closing{if !pay_many(cx,1,size_of::<bool>(),0)?{return Ok(false)}self.closing=true;return Ok(false)}if self.returned{if !self.slot.settle_step(cx)?{return Ok(false)}if !pay_many(cx,3,3*size_of::<bool>(),0)?{return Ok(false)}self.acquired=false;self.returned=false;self.ready=false;return Ok(false)}if !self.acquired&&!self.slot.lend_step(&mut self.seed,&mut self.acquired,cx)?{return Ok(false)}if let Some(home)=self.seed.as_mut(){if !home.close_on_source(cx)?{return Ok(false)}if !pay_many(cx,1,size_of::<Option<ActorFailureRecipientHome>>(),0)?{return Ok(false)}self.seed.take();return Ok(false)}self.slot.return_owner_step(&mut self.seed,&mut self.returned,cx)?;if self.slot.terminal_is_empty(){return Err(refused().into())}Ok(false)}fn terminal_is_empty(&self)->bool{self.binding.is_none()&&self.home==0&&self.slot.terminal_is_empty()&&self.seed.is_none()&&!self.acquired&&!self.returned&&!self.ready}} 

#[cfg(test)]mod tests{use super::*;use semio_framework_job::{OperationId,Generation};use semio_framework_job_testing_caller::OriginalJobFixtureCaller;use semio_framework_value::RetainedCloneGrant;use semio_framework_value_testing_allocator::observe_retirement_allocations as observe;fn clock()->Option<u64>{Some(1)}#[test]fn actor_failure_recipient_seed_and_cancel_retire_actual_source_claims(){let stock=RetainedCloneGrant{maximum_items:1_000_000,maximum_copy_bytes:32_000_000,maximum_capacity_bytes:32_000_000,maximum_release_bytes:32_000_000,maximum_depth:128};let grant=RetainedCloneGrant{maximum_items:128,maximum_copy_bytes:65536,maximum_capacity_bytes:65536,maximum_release_bytes:65536,maximum_depth:64};let mut caller=OriginalJobFixtureCaller::admit(OperationId(887),Generation(1),stock,clock,100_000_000,10_000_000);let mut foreign=OriginalJobFixtureCaller::admit(OperationId(888),Generation(1),stock,clock,100_000_000,10_000_000);let mut recipient=ActorFailureRecipient::empty();assert!(!caller.turn(RetainedCloneGrant{maximum_items:0,..grant},|cx|recipient.prepare_step(cx)).unwrap());assert!(recipient.terminal_is_empty());for _ in 0..4096{let(result,heap)=observe(||caller.turn(grant,|cx|recipient.prepare_step(cx)));let receipt=caller.receipt();assert_eq!(heap,(receipt.retained_capacity_bytes,receipt.released_bytes));if result.unwrap(){break}}assert!(recipient.ready);assert!(recipient.slot.peek().is_some());let(result,heap)=observe(||foreign.turn(grant,|cx|cx.with_original_retirement(|cx|recipient.close_on_source(cx))));assert!(result.is_err());assert_eq!(heap,(0,0));assert_eq!(foreign.receipt(),Default::default());caller.cancel().cancel_now();for _ in 0..4096{let(result,heap)=observe(||caller.turn(grant,|cx|cx.with_original_retirement(|cx|recipient.close_on_source(cx))));let receipt=caller.receipt();assert_eq!(heap,(receipt.retained_capacity_bytes,receipt.released_bytes));if result.unwrap(){break}}assert!(recipient.terminal_is_empty());let(_,heap)=observe(||drop(recipient));assert_eq!(heap,(0,0));foreign.retire(grant);caller.retire(grant);}}
